using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BOInspect {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 edit required");string h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B2_OperationsRebuild/"));Directory.CreateDirectory(h);if(!File.Exists(h+"before.unity.txt"))File.Copy(s.path,h+"before.unity.txt");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();Func<Vector3,float[]> v=p=>new[]{p.x,p.y,p.z};var data=all.Select(t=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),t.name,parent=t.parent?.name,position=v(t.position),local=v(t.localPosition),rotation=v(t.localEulerAngles),scale=v(t.localScale),active=t.gameObject.activeSelf,enabled=t.gameObject.activeInHierarchy,asset=PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)?PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject):"",colliders=t.GetComponents<Collider>().Select(c=>new{type=c.GetType().Name,center=v(c.bounds.center),size=v(c.bounds.size)}).ToArray()}).ToArray();File.WriteAllText(h+"before.json",JsonConvert.SerializeObject(data,Formatting.Indented));return new{objects=all.Length,roots=s.GetRootGameObjects().Select(g=>g.name)};}
}
